cd /workspace/project && python3 << 'EOF'
import paramiko
client = paramiko.SSHClient()
client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
client.connect("46.202.154.25", 22, "root", "2N00py123+++")
# Get full nginx config
stdin, stdout, stderr = client.exec_command("cat /etc/nginx/sites-enabled/arelorian.de 2>&1")
print("Current config:", stdout.read().decode())
client.close()
EOF
Current config: server {
    listen 80;
    listen [::]:80;
    server_name arelorian.de www.arelorian.de;
    location /.well-known/acme-challenge/ { root /var/www/html; }
    location / { return 301 https://$host$request_uri; }
}

upstream arelorian_upstream {
    server 127.0.0.1:3000 max_fails=3 fail_timeout=10s;
    keepalive 32;
}

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name arelorian.de www.arelorian.de;

    ssl_certificate     /etc/letsencrypt/live/arelorian.de/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/arelorian.de/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;

    client_max_body_size 50M;
    gzip on;
    gzip_types text/plain text/css application/javascript application/json image/svg+xml;

    # Static SPA root (used as fallback when backend on :3000 is down)
    root /root/opt/areloria/client/dist;
    index index.html;

    # On upstream failure -> serve static SPA
    error_page 502 503 504 = @static_fallback;

    location / {
        proxy_pass http://arelorian_upstream;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 90s;
        proxy_connect_timeout 5s;
        proxy_intercept_errors on;
        proxy_next_upstream error timeout http_502 http_503 http_504;
    }

    location /socket.io/ {
        proxy_pass http://arelorian_upstream;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 3600s;
    }

    location @static_fallback {
        internal;
        root /root/opt/areloria/client/dist;
        try_files $uri /index.html =404;
        add_header X-Served-By "nginx-static-fallback" always;
    }

    location = /nginx-health {
        access_log off;
        default_type text/plain;
        return 200 "ok\n";
    }
}
